INSERT INTO products (id, name, price, image_url, description, category) VALUES
('elden-ring', 'Elden Ring: Shadow of the Erdtree', 39.99, '/images/elden.jpg', 'An expansion featuring an all-new story set in the Land of Shadow, filled with new bosses, dungeons, and equipment.', 'Action RPG'),
('cyberpunk-2077', 'Cyberpunk 2077: Ultimate Edition', 59.99, '/images/cyberpunk.jpg', 'An open-world, action-adventure RPG set in Night City. You play as V, a mercenary outlaw fighting for survival.', 'Sci-Fi RPG'),
('hades-ii', 'Hades II', 29.99, '/images/hades2.jpg', 'Battle beyond the Underworld using dark sorcery to take on the Titan of Time in this rogue-like dungeon crawler.', 'Rogue-like RPG'),
('baldurs-gate-3', 'Baldur''s Gate 3', 59.99, '/images/bg3.jpg', 'Gather your party and return to the Forgotten Realms in a tale of fellowship and betrayal, sacrifice and survival.', 'RPG'),
('celeste', 'Celeste', 19.99, '/images/celeste.jpg', 'Help Madeline survive her inner demons on her journey to the top of Celeste Mountain, in this super-tight platformer.', 'Platformer'),
('metroid-prime', 'Metroid Prime Remastered', 39.99, '/images/metroid.jpg', 'The first-person platforming classic, fully remastered for Nintendo Switch with modern controls, visuals, and audio.', 'Action Adventure');

