INSERT INTO page_drafts (page_id, content_json)
VALUES (
  'homepage',
  '{"id":"homepage","slug":"/","seo":{"title":"ACREE | Premium Gaming Store","description":"Welcome to ACREE, the ultimate destination for premium games, digital keys, and live tournament events.","ogImage":"/images/hero-bg.jpg"},"sections":[{"id":"promo-1","type":"promoBanner","props":{"text":"Summer Games Showcase! Save up to 50% on selected digital keys.","bgColor":"#1e1b4b","textColor":"#e0e7ff","link":"#featured-products"}},{"id":"hero-1","type":"hero","props":{"title":"Unleash Next-Gen Gaming","subtitle":"Discover handpicked masterpieces, direct digital downloads, and exclusive keys with instant email delivery.","backgroundImage":"/images/hero-bg.jpg","ctaText":"Browse Catalog","ctaLink":"#featured-products"}},{"id":"featured-1","type":"featuredProducts","props":{"title":"Featured Masterpieces","subtitle":"Highly rated, critically acclaimed games ready to play today.","productIds":["elden-ring","cyberpunk-2077","hades-ii","baldurs-gate-3"]}},{"id":"event-1","type":"eventBanner","props":{"title":"Cyber Tournament 2026","description":"Join our annual speedrunning and competitive esports tournament live stream. Register now for early bracket entry and exclusive in-game rewards.","date":"June 24, 2026","image":"/images/event-banner.jpg","ctaText":"Register Now","ctaLink":"#register"}},{"id":"testimonials-1","type":"testimonials","props":{"title":"What Our Players Say","items":[{"quote":"ACREE has the fastest key delivery I''ve ever experienced. I bought Elden Ring and was in the game in less than 2 minutes!","author":"Marcus V.","role":"Verified Buyer","avatar":"/images/avatar-marcus.jpg"},{"quote":"The customer support is incredible. I had an issue with an epic key and they resolved it in less than 5 minutes.","author":"Elena R.","role":"Community Member","avatar":"/images/avatar-elena.jpg"}]}},{"id":"cta-1","type":"cta","props":{"title":"Join the ACREE Guild","subtitle":"Sign up for our newsletter to receive weekly discount codes, tournament announcements, and developer interviews.","buttonText":"Join Newsletter","buttonLink":"#newsletter"}},{"id":"faq-1","type":"faq","props":{"title":"Frequently Asked Questions","items":[{"question":"How do I redeem my game key?","answer":"Once your payment is confirmed, the digital key is displayed immediately on the confirmation page and emailed to you. You can redeem it on Steam, Epic Games, or the respective console storefront."},{"question":"Are the keys authorized?","answer":"Yes, all game keys sold on ACREE are sourced directly from authorized publishers and distributors. We guarantee 100% genuine keys."},{"question":"What is your refund policy?","answer":"We offer a 14-day refund policy on unredeemed game keys. Once a key has been revealed or activated, it cannot be refunded."}]}}]}'
);

